fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    let n = v.len();
    debug_assert!(n > 0);

    // We maintain an active interval [lo, hi] (both inclusive) that:
    // - stays within bounds,
    // - contains at least one occurrence of k (by problem assumption),
    // - strictly shrinks each iteration.
    let mut lo: usize = 0;
    let mut hi: usize = n - 1;

    while lo < hi {
        // Midpoint chosen to avoid overflow.
        let mid = lo + (hi - lo) / 2;

        if v[mid] < k {
            // k must be to the right of mid.
            lo = mid + 1;
        } else if v[mid] > k {
            // k must be to the left of mid.
            hi = mid.saturating_sub(1);
        } else {
            // Found an occurrence; returning any valid index is allowed.
            return mid;
        }
    }

    // Interval collapsed to a single index; by assumption, k occurs in the array.
    debug_assert!(v[lo] == k);
    lo
}